1	/**
2	 * The offline-faithful rebuild of the `angular-super-productivity-v2-13-15`
3	 * migrated lane.
4	 *
5	 * u21 read the emitted `app/dist/index.html` of the lane u18j published and
6	 * found forty-five `@font-face` rules that exist in no input: the Angular 16
7	 * browser builder's font inliner had gone to `fonts.googleapis.com` during the
8	 * build — for the Roboto stylesheet this application's own `index.html` links —
9	 * and pasted the answer into the document. That is a build-time third-party
10	 * request nobody declared, and it makes the emitted bytes a property of what a
11	 * font host served on the build day. The capability that turns it off is landed
12	 * in `@versionless/angular`; this driver applies it to the staged workspace and
13	 * rebuilds the lane.
14	 *
15	 * The driver measures rather than asserts. Every build it runs — including the
16	 * control it runs BEFORE applying the capability — runs under the in-process
17	 * egress guard u22 wrote, which refuses and records any connection to a
18	 * non-loopback address. The control is the point: a build of the workspace as
19	 * u18j left it is expected to reach for the font host and to fail when it
20	 * cannot, which is what makes the green build afterwards evidence of something.
21	 * A control that came back green would mean the fetch was being served from
22	 * somewhere and this whole round would be measuring nothing.
23	 *
24	 * Nothing about fonts, hosts or this application is decided here. Which targets
25	 * carry the option and what value it takes is read out of the capability, whose
26	 * only inputs are the builder name and the shape of the declared `optimization`
27	 * value; the guard and the workspace application are u22's, run against this
28	 * lane's tree rather than copied.
29	 */
30	
31	import { readFile, rm, writeFile } from 'node:fs/promises';
32	import { spawn } from 'node:child_process';
33	import * as path from 'pathe';
34	import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-super-productivity-apply-run.ts';
35	import {
36		applyFontInliningDisable,
37		EGRESS_GUARD_SOURCE,
38		type BuildReading,
39		type EgressAttempt,
40		type WorkspaceApplication,
41	} from './angular-tiny-translator-u22-font-run.ts';
42	
43	export const UNIT = 'lrapr-t006/u23-super-productivity-offline-rebuild';
44	/** The output roots this round emits: the canonical one and its repeat. */
45	export const CANONICAL_ROOT = 'dist-23';
46	export const REPEATED_ROOT = 'dist-24';
47	/** The control build, run before the capability is applied and expected red. */
48	export const CONTROL_ROOT = 'dist-offline-control';
49	/** The Angular 16 cell's Node runtime, already materialised in this checkout. */
50	const NODE_BIN = path.join(
51		path.resolve(import.meta.dirname, '../../../..'),
52		'.versionless/cache/angular-jira-clone-runtime/node-v16.20.2-darwin-arm64/bin',
53	);
54	
55	/**
56	 * The build this cell's records have always run: the repository's own
57	 * `buildFrontend` heap size, the modern configuration name, and the CLI entry
58	 * point invoked through the era runtime rather than through `npx`.
59	 */
60	const BUILD_ARGUMENTS: readonly string[] = Object.freeze([
61		'--max_old_space_size=4096',
62		'./node_modules/@angular/cli/bin/ng.js',
63		'build',
64		'--configuration',
65		'production',
66	]);
67	
68	/** Every non-loopback attempt one guarded build made, in the order it made them. */
69	async function readEgress(logFile: string): Promise<readonly EgressAttempt[]> {
70		const text = await readFile(logFile, 'utf8').catch(() => '');
71		return Object.freeze(
72			text
73				.split('\n')
74				.filter((line) => line.length > 0)
75				.map((line) => JSON.parse(line) as EgressAttempt),
76		);
77	}
78	
79	/** The one line of a build log that says why an inlining build died. */
80	function failureLine(log: string): string | null {
81		const line = log.split('\n').find((entry) => entry.includes('Inlining of fonts failed'));
82		return line === undefined ? null : line.trim();
83	}
84	
85	/**
86	 * Run one production build under the egress guard, into a cleaned output root.
87	 *
88	 * The output root is removed first so a build that emits nothing cannot be read
89	 * as a build that emitted what the previous one left behind, and the guard log
90	 * is removed with it so each reading belongs to exactly one build.
91	 */
92	export async function guardedBuild(name: string, outputRoot: string): Promise<BuildReading> {
93		const guard = path.join(STAGE_DIRECTORY, 'egress-guard.cjs');
94		const egressLog = path.join(STAGE_DIRECTORY, `${name}.egress.jsonl`);
95		await writeFile(guard, EGRESS_GUARD_SOURCE);
96		await rm(egressLog, { force: true });
97		await writeFile(egressLog, '');
98		await rm(path.join(STAGE_DIRECTORY, outputRoot), { recursive: true, force: true });
99		const argv = [...BUILD_ARGUMENTS, '--output-path', `../${outputRoot}`];
100		const command = `node ${argv.join(' ')}`;
101		const { code, stdout, stderr } = await new Promise<{
102			code: number;
103			stdout: string;
104			stderr: string;
105		}>((settle, fail) => {
106			let out = '';
107			let err = '';
108			const child = spawn(path.join(NODE_BIN, 'node'), argv, {
109				cwd: APPLIED_TREE,
110				env: {
111					...process.env,
112					PATH: `${NODE_BIN}:${process.env['PATH'] ?? ''}`,
113					NODE_OPTIONS: `--require ${guard}`,
114					VERSIONLESS_EGRESS_LOG: egressLog,
115					VERSIONLESS_NETWORK_MODE: 'offline',
116					NPM_CONFIG_OFFLINE: 'true',
117					NG_CLI_ANALYTICS: 'false',
118				},
119			});
120			child.stdout.on('data', (chunk: Buffer) => (out += chunk.toString('utf8')));
121			child.stderr.on('data', (chunk: Buffer) => (err += chunk.toString('utf8')));
122			child.on('error', fail);
123			child.on('close', (status) => settle({ code: status ?? -1, stdout: out, stderr: err }));
124		});
125		await writeFile(path.join(STAGE_DIRECTORY, `${name}.exit`), `${String(code)}\n`);
126		await writeFile(path.join(STAGE_DIRECTORY, `${name}.log`), `${stdout}\n${stderr}`);
127		return Object.freeze({
128			name,
129			command,
130			outputRoot,
131			exitStatus: code,
132			bundleLines: stdout.split('\n').filter((line) => line.includes('.js')).length,
133			egressAttempts: await readEgress(egressLog),
134			failure: failureLine(`${stdout}\n${stderr}`),
135		});
136	}
137	
138	export type FontRound = Readonly<{
139		control: BuildReading;
140		application: WorkspaceApplication;
141		builds: readonly BuildReading[];
142	}>;
143	
144	/**
145	 * The whole round, in the only order that makes it evidence: control first,
146	 * against the workspace as u18j left it, then the capability, then the two
147	 * builds the lane publishes.
148	 */
149	export async function runFontRound(): Promise<FontRound> {
150		const control = await guardedBuild('build-offline-control', CONTROL_ROOT);
151		const application = await applyFontInliningDisable(APPLIED_TREE);
152		const first = await guardedBuild('build-23', CANONICAL_ROOT);
153		const second = await guardedBuild('build-24', REPEATED_ROOT);
154		return Object.freeze({ control, application, builds: Object.freeze([first, second]) });
155	}
156	
157	export async function main(): Promise<void> {
158		const round = await runFontRound();
159		await writeFile(
160			path.join(STAGE_DIRECTORY, 'u23-font-round.json'),
161			`${JSON.stringify(round, null, '\t')}\n`,
162		);
163		process.stdout.write(
164			`control exit ${String(round.control.exitStatus)}, ` +
165				`${String(round.control.egressAttempts.length)} egress attempt(s)\n`,
166		);
167		for (const site of round.application.sites) process.stdout.write(`applied: ${site.at}\n`);
168		for (const build of round.builds)
169			process.stdout.write(
170				`${build.name} exit ${String(build.exitStatus)}, ` +
171					`${String(build.egressAttempts.length)} egress attempt(s)\n`,
172			);
173	}
174	
175	if (process.argv[1]?.endsWith('angular-super-productivity-u23-font-run.ts'))
176		main().catch((error: unknown) => {
177			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
178			process.exitCode = 1;
179		});
