1	/**
2	 * Apply the composed `@versionless/angular` changeset to a stage copy of the
3	 * pinned `angular-super-productivity-v2-13-15` tree, so a closure can be
4	 * installed into it and a production build attempted on the bytes the adapter
5	 * produced.
6	 *
7	 * u18 composed the changeset and recorded it; it built nothing. This driver is
8	 * the owed half's first step: the same composition, written into a tree.
9	 *
10	 * The driver is fixture-scoped — it knows where this fixture's stage tree was
11	 * materialised, and nothing else. Every decision about *what to change* lives
12	 * in `@versionless/angular`, which knows nothing about this application.
13	 */
14	
15	import { mkdir, writeFile } from 'node:fs/promises';
16	import * as path from 'pathe';
17	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
18	import { sealRecord, verifySealedRecord, type SealedRecord } from './angular-factoriolab-build-lanes-run.ts';
19	import { applyMigration, type Application } from './angular-tiny-translator-apply-run.ts';
20	import type { AngularMigration } from '../../../frameworks/angular/src/index.ts';
21	import { composeMigration, CONSENT, EVIDENCE_DIRECTORY, SOURCE_TREE } from './angular-super-productivity-lanes-run.ts';
22	
23	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
24	
25	export const UNIT = 'lrapr-t006/u18b-super-productivity-migrated-lane';
26	
27	export const STAGE_DIRECTORY = path.join(
28		repositoryRoot,
29		'.versionless/stage/angular-super-productivity-v2-13-15-u18b',
30	);
31	/** The pinned revision with the changeset written into it; the build tree. */
32	export const APPLIED_TREE = path.join(STAGE_DIRECTORY, 'app');
33	
34	export const MIGRATION_RECORD_FILE = 'u18b-source-migration.json';
35	
36	export { EVIDENCE_DIRECTORY };
37	
38	/**
39	 * The applied-changeset record. Digests before and after are the changeset's;
40	 * what this record adds is that the bytes were written into a named tree.
41	 */
42	export function buildApplicationRecord(
43		migration: AngularMigration,
44		applied: Application,
45	): SealedRecord {
46		return sealRecord({
47			schemaVersion: 'versionless.angular-super-productivity-source-migration.v1',
48			unit: UNIT,
49			consentId: CONSENT,
50			cell: migration.cell,
51			appliedTo: {
52				tree: '.versionless/stage/angular-super-productivity-v2-13-15-u18b/app',
53				from: '.versionless/cache/angular-super-productivity-v2-13-15-source/verify/extracted',
54				commit: '2943c5c4f13c3ce4dece0abf4f9c39739dde4192',
55				excludedFromStage: ['node_modules', '.git'],
56				excludedReason:
57					'The stage copy carries the repository tree and nothing installed or version-controlled: node_modules is what the install below creates, and .git is not a build input.',
58			},
59			applicationFilesScanned: migration.applicationFilesScanned,
60			applicationFilesChanged: migration.applicationFilesChanged,
61			workspaceFilesChanged: migration.workspaceFilesChanged,
62			filesWritten: applied.written,
63			filesRemoved: applied.removed,
64			files: migration.files.map((entry) => ({
65				path: entry.path,
66				kind: entry.kind,
67				changed: entry.changed,
68				sha256Before: entry.sha256Before,
69				sha256After: entry.sha256After,
70				changes: entry.changes,
71			})),
72			declaredDifferences: migration.declaredDifferences,
73			unhandled: migration.unhandled,
74			notEstablished: [
75				'Writing a changeset into a tree is not a build. Nothing here establishes that the applied tree installs, compiles or emits anything; the lane record beside this one states what happened when that was attempted.',
76				'`applicationFilesChanged` counts application source a transform rewrote. A file the adapter scanned and left alone is counted as scanned and not as changed.',
77			],
78		});
79	}
80	
81	export async function main(): Promise<void> {
82		const migration = await composeMigration(SOURCE_TREE);
83		const applied = await applyMigration(migration, APPLIED_TREE);
84		const record = verifySealedRecord(buildApplicationRecord(migration, applied));
85		await mkdir(EVIDENCE_DIRECTORY, { recursive: true });
86		await writeFile(path.join(EVIDENCE_DIRECTORY, MIGRATION_RECORD_FILE), canonical(record));
87		process.stdout.write(
88			`applied ${String(applied.written.length)} files (${String(
89				migration.applicationFilesChanged,
90			)}/${String(migration.applicationFilesScanned)} application, ${String(
91				migration.workspaceFilesChanged,
92			)} workspace), removed ${String(applied.removed.length)}, ` +
93				`${String(migration.unhandled.length)} unhandled; record digest ${sha256(
94					canonical(record),
95				).slice(0, 12)}\n`,
96		);
97	}
98	
99	if (process.argv[1]?.endsWith('angular-super-productivity-apply-run.ts'))
100		main().catch((error: unknown) => {
101			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
102			process.exitCode = 1;
103		});
